  async fetch(request, env) {
    let response;
    try {
      response = await dispatch(request, env);
    } catch (error) {
      response = new Response("Internal error", { status: 500 });
    }
    response.headers.set("X-Content-Type-Options", "nosniff");
    return response;
  }
};

