export default {
  async fetch(request, env) {
    const path = new URL(request.url).pathname;
    if (request.method === "GET" && path === "/mint") {
      return Response.json({ token: crypto.randomUUID(), record: { sub: "operator-selects-subject", expiresAt: Date.now() + 3600000 } });
    }
    const match = /^\/objects\/([A-Za-z0-9_-]{1,64})$/.exec(path);
    if (!match) return new Response("Not found", { status: 404 });
    const key = match[1];
    if (request.method === "GET") {
      const object = await env.BUCKET.get(key);
      return object ? new Response(object.body, { headers: { "Content-Type": "text/plain" } }) : new Response("Not found", { status: 404 });
    }
    if (request.method !== "PUT") return new Response("Method not allowed", { status: 405 });
    const authorization = request.headers.get("Authorization") || "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7) : "";
    const capability = token ? await env.CAPS.get(token, "json") : null;
    if (!capability) return new Response("Unauthorized", { status: 401 });
    if (Date.now() >= capability.expiresAt) return new Response("Expired", { status: 401 });
    const existing = await env.BUCKET.head(key);
    if (existing && existing.customMetadata.owner !== capability.sub) return new Response("Forbidden", { status: 403 });
    await env.BUCKET.put(key, request.body, { customMetadata: { owner: capability.sub }, httpMetadata: { contentType: "text/plain" } });
    return new Response("saved");
  }
};

